{
  "justification": "This unprompted salience index records which issues were raised, not what respondents wanted done, and most attention is on valence/economic items (NHS, education, unemployment, economy) that sit largely outside the GAL–TAN axis. Where the axis is engaged, concerns about crime/law and order and traditional norms/defence noticeably outweigh environmental or multicultural cues, so I assign a slight TAN lean.",
  "poles": [
    {
      "pole": "tan",
      "basis": "Crime/Law and order/Violence/Vandalism (27%); Morality/Individual behaviour (5%); Defence/Foreign affairs/International terrorism (2%); EU/Europe noted but direction ambiguous",
      "weight": 0.55
    },
    {
      "pole": "gal",
      "basis": "Pollution/Environment (2%); Race relations/Immigration (3%) and EU/Europe are ambiguous but can include multicultural/integration concerns",
      "weight": 0.45
    }
  ]
}
